<?php defined('_JEXEC') or die;use Joomla\CMS\Editor\Editor;use Joomla\CMS\Factory;use Joomla\CMS\HTML\HTMLHelper;use Joomla\CMS\Router\Route;$editor=Editor::getInstance((string)Factory::getApplication()->getIdentity()->getParam('editor','tinymce'));?>
<div class="row g-3 mb-4"><div class="col-md-6"><div class="card card-body"><strong><?php echo $this->pending;?></strong><span>Queued messages</span></div></div><div class="col-md-6"><div class="card card-body"><strong><?php echo $this->failed;?></strong><span>Failed messages</span></div></div></div>
<div class="d-flex gap-2 mb-3"><form action="<?php echo Route::_('index.php?option=com_blog&task=newsletter.send');?>" method="post"><button class="btn btn-success" type="submit" <?php echo $this->pending?'':'disabled';?>>Send next queued batch (25)</button><?php echo HTMLHelper::_('form.token');?></form><form action="<?php echo Route::_('index.php?option=com_blog&task=newsletter.retry');?>" method="post"><button class="btn btn-warning" type="submit" <?php echo $this->failed?'':'disabled';?>>Retry failed messages</button><?php echo HTMLHelper::_('form.token');?></form></div>
<form action="<?php echo Route::_('index.php?option=com_blog&task=newsletter.queue');?>" method="post" id="adminForm"><div class="card card-body"><label class="form-label">Load saved template</label><select class="form-select mb-3" id="newsletter-template"><option value="">Start with a blank email</option><?php foreach($this->templates as $template):?><option value="<?php echo (int)$template->id;?>"><?php echo htmlspecialchars($template->title,ENT_QUOTES,'UTF-8');?></option><?php endforeach;?></select><label class="form-label">Template name</label><input class="form-control mb-3" name="template_title" placeholder="Optional — save this email as a reusable template"><label class="form-label">Email subject</label><input class="form-control mb-3" name="subject" id="newsletter-subject" required><div class="row g-3 mb-3"><div class="col-md-6"><label class="form-label">Recipients</label><select class="form-select" name="segment"><option value="all">All active subscribers</option><option value="recent30">Subscribed in the last 30 days</option><option value="recent90">Subscribed in the last 90 days</option></select></div><div class="col-md-6"><label class="form-label">Schedule send (optional)</label><input class="form-control" type="datetime-local" name="scheduled_at"><div class="form-text">Leave blank to queue immediately.</div></div></div><label class="form-label">Message</label><?php echo $editor->display('body','','100%','500','60','20',true,null,null,null,['relative_urls'=>false]);?><p class="form-text">Available placeholders: {name}, {email}, {unsubscribe_url}</p><label class="form-check mb-3"><input class="form-check-input" type="checkbox" name="save_template" value="1"><span class="form-check-label">Save as reusable template</span></label><label class="form-label">Test recipient</label><input class="form-control mb-3" type="email" name="test_email" placeholder="Leave blank to use your administrator email"><div class="d-flex gap-2"><button class="btn btn-primary" type="submit">Create or schedule campaign</button><button class="btn btn-info" type="submit" formaction="<?php echo Route::_('index.php?option=com_blog&task=newsletter.test');?>">Send test email</button><button class="btn btn-secondary" type="button" id="newsletter-preview">Preview email</button></div></div><?php echo HTMLHelper::_('form.token');?></form>
<h2 class="mt-4">Campaign history</h2><table class="table"><thead><tr><th>Subject</th><th>Created</th><th>Recipients</th><th>Sent</th><th>Queued</th><th>Failed</th><th>Skipped</th></tr></thead><tbody><?php foreach($this->campaigns as $campaign):?><tr><td><a href="<?php echo Route::_('index.php?option=com_blog&view=campaign&id='.(int)$campaign->id);?>"><?php echo htmlspecialchars($campaign->subject,ENT_QUOTES,'UTF-8');?></a></td><td><?php echo htmlspecialchars($campaign->created,ENT_QUOTES,'UTF-8');?></td><td><?php echo (int)$campaign->recipients;?></td><td><?php echo (int)$campaign->sent;?></td><td><?php echo (int)$campaign->pending;?></td><td><?php echo (int)$campaign->failed;?></td><td><?php echo (int)$campaign->skipped;?></td></tr><?php endforeach;?></tbody></table>
<dialog id="newsletter-preview-dialog" class="border-0 rounded shadow-lg p-0" style="width:min(900px,calc(100vw - 2rem))"><header class="border-bottom p-3 d-flex justify-content-between"><strong id="newsletter-preview-subject"></strong><button class="btn-close" type="button" onclick="this.closest('dialog').close()"></button></header><div class="p-4" id="newsletter-preview-body"></div></dialog>
<script type="application/json" id="newsletter-template-data"><?php echo json_encode($this->templates,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);?></script><script>document.addEventListener('DOMContentLoaded',()=>{const templates=JSON.parse(document.getElementById('newsletter-template-data').textContent||'[]');const value=()=>Joomla.editors?.instances?.body?.getValue?.()??document.getElementById('body')?.value??'';const setValue=v=>{Joomla.editors?.instances?.body?.setValue?.(v);const field=document.getElementById('body');if(field)field.value=v};document.getElementById('newsletter-template').addEventListener('change',e=>{const item=templates.find(x=>String(x.id)===e.target.value);if(item){document.getElementById('newsletter-subject').value=item.subject;setValue(item.body)}});document.getElementById('newsletter-preview').addEventListener('click',()=>{document.getElementById('newsletter-preview-subject').textContent=document.getElementById('newsletter-subject').value||'Email preview';document.getElementById('newsletter-preview-body').innerHTML=value();document.getElementById('newsletter-preview-dialog').showModal()})});</script>
